head.script:
scwin.gVar = {
    "bReady" : false,
}



// 테스트 설명, 유효성 값 설정
//  - 발생 조건 축(포커스 해제 / setValue / 값 변경 없음 / Enter) 과 info 파라미터를 담당한다.
//  - ref 바인딩 DataCollection 의 데이터 선택 변경은 secret_E_onviewchange_2.xml, 이벤트 발생 순서는 secret_E_onviewchange_3.xml 에서 검증한다.
//  - onchange 는 스크립트 등 다른 원인에 의한 변경까지 처리된다는 @spec 의 대비 출력으로만 사용한다.
scwin.tData = {
    "description" : "[secret > E > onviewchange]<br/>Secret 컴포넌트에서 사용자의 조작에 의해 입력값이 변경된 후 포커스가 해제될때 발생합니다.",
    "validation" : [
        "Secret 컴포넌트에서 사용자의 조작에 의해 입력값이 변경된 후 포커스가 해제될때 onviewchange 이벤트가 발생합니다.",
        "스크립트에서 setValue() 메소드로 입력값을 변경한 경우 onviewchange 이벤트는 발생하지 않습니다.",
        "info 파라미터로 변경된 입력값에 대한 정보가 객체로 전달됩니다.",
        "info.oldValue 속성으로 변경되기 전 입력값을 마스킹되지 않은 평문 문자열로 갖습니다.",
        "info.newValue 속성으로 변경된 후 입력값을 마스킹되지 않은 평문 문자열로 갖습니다.",
        "입력값에 변경이 없으면 onviewchange 이벤트는 발생하지 않습니다.",
        "입력값이 변경된 상태로 Enter 키 입력 시 onchange 이벤트가 발생합니다.",
        "사용자의 입력뿐만 아니라 스크립트 등 다른 원인에 의해 값이 변경된 경우도 처리하려면 onchange 이벤트를 사용하여야 합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 생성 중 헬퍼의 초기값 설정으로 발생하는 이벤트는 출력하지 않음
    scwin.gVar["bReady"] = false;

    // 기존 컴포넌트 있으면 삭제
    if (typeof label1 !== 'undefined') {
        label1.remove();
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    $c.gcm.createLabel('label="[전제] target1 은 Secret 컴포넌트이며 생성 직후 초기값 secret 이 설정됩니다 (화면에는 마스킹 표시)\n[절차] 아래 중 하나를 수행\n - 포커스 해제 : target1 클릭 -> 값 입력 -> 바깥 영역 클릭\n - Enter : target1 클릭 -> 값 입력 -> Enter\n - 값 변경 없음 : target1 클릭 -> 입력 없이 바깥 영역 클릭 (또는 입력 후 원래 값으로 되돌리고 바깥 영역 클릭)\n - setValue : target1 에 포커스를 주지 않은 상태에서 value 입력 -> setValue 클릭\n[확인] 결과창의 onviewchange 발생 줄과 info.oldValue, info.newValue 값, 대비용 onchange 발생 줄 출현 여부"', '', 'label1');

    let eList = $c.gcm.createEList(["onviewchange", "onchange"]);

    // comp 생성 함수 호출 (헬퍼가 생성 직후 setValue 로 초기값 secret 설정)
    await $c.gcm.createBasicSecret('', eList);

    scwin.gVar["bReady"] = true;
}



// setValue 실행 (포커스와 무관한 스크립트 변경 수단) - validation 2, 8 발동 수단
scwin.btn_setValue_onclick = function (e) {
    let strParam = par_value.getValue();

    wf_body_bottom.getObj("scwin").setReturnValue("setValue(" + strParam + ") 호출 -> 호출 전 값 : " + target1.getValue());

    target1.setValue(strParam);
}



// validation 1 ~ 7 판정 출력 (info 속성 개별 출력)
scwin.target1_onviewchange = function (info) {
    if (!scwin.gVar["bReady"])
        return;

    wf_body_bottom.getObj("scwin").setReturnValue("▶ onviewchange 발생 / 화면 입력창 type : " + target1.render.type);
    wf_body_bottom.getObj("scwin").setReturnValue("info.oldValue : " + info.oldValue + " (" + typeof info.oldValue + ")");
    wf_body_bottom.getObj("scwin").setReturnValue("info.newValue : " + info.newValue + " (" + typeof info.newValue + ")");
}



// validation 2, 7, 8 대비 출력 (setValue 로도 발생 = onviewchange 와 대비)
scwin.target1_onchange = function (info) {
    if (!scwin.gVar["bReady"])
        return;

    wf_body_bottom.getObj("scwin").setReturnValue("▶ onchange 발생");
}
